import java.util.List;

class Box<T> {
    private T value;                              // T is whatever the user chose.
    Box(T value) { this.value = value; }
    T get() { return value; }
    void set(T value) { this.value = value; }
}

public class Generics {
    static <T> T first(List<T> items) {           // <T> declared before return type.
        if (items.isEmpty()) throw new IllegalArgumentException("empty");
        return items.get(0);
    }

    public static void main(String[] args) {
        Box<String> name = new Box<>("Ada");     // diamond infers String.
        String s = name.get();                      // no cast needed.
        // name.set(42);                            // compile error: int is not String.
        Integer n = first(List.of(7, 8, 9));        // T inferred as Integer.
        System.out.println(s + " " + n);           // Ada 7
    }
}
